showAssetTab=function(id,tab){baseAssetTab(id,tab);applyRoles();if(tab==='Dependencies'){const t=traceFrom(id);const values=$('assetTabContent').querySelectorAll('.mini b');if(values[2])values[2].textContent=fmt(t.pop||0)}if(state.user.role!=='admin')$('assetTabContent').querySelectorAll('button[onclick*="runSimulation"]').forEach(b=>b.hidden=true)};
